# Frozen event-history models; all fitted artifacts contain data only.
.sv_scalar<-function(x,name,low=-Inf,high=Inf){v<-.cr_numeric(x,name);if(length(v)!=1L||!is.null(dim(v))||v<low||v>high).cr_error('INVALID_INPUT',paste(name,'outside scalar domain'));as.numeric(v)}
.sv_strings<-function(x,name,empty=FALSE){x<-unlist(x,use.names=FALSE);if(!length(x))x<-character();if((!empty&&!length(x))||(length(x)&&(!is.character(x)||anyNA(x)||any(!nzchar(x))))||anyDuplicated(x)).cr_error('INVALID_INPUT',paste(name,'requires distinct nonempty names'));x}
.sv_rows<-function(x){if(!is.list(x)||!is.null(names(x))||!length(x)||any(!vapply(x,is.list,logical(1)))).cr_error('INVALID_TABLE','Nonempty records required');x}
.sv_model<-function(method,features,parameters,target,training,model_id,model_version,diagnostics){if(!is.list(target)||!identical(target$probability_measure,'PHYSICAL')).cr_error('INCOMPATIBLE_TARGET','Physical event target required');.cr_model(list(schema_version='1.0',model_id=model_id,model_version=model_version,method_id=paste0('survival.',method),feature_order=as.list(features),parameters=parameters,preprocessing=list(transformation='identity'),target=target,training=training,diagnostics=diagnostics,provenance=list(data_origin=if(is.null(training$data_origin))'USER_SUPPLIED' else training$data_origin,parameter_origin='ESTIMATED')))}
.sv_times<-function(entry_time,exit_time,event_indicator){stop<-.cr_numeric(exit_time,'exit_time',vector_only=TRUE);start<-if(is.null(entry_time))rep(0,length(stop)) else .cr_numeric(entry_time,'entry_time',vector_only=TRUE);event<-.cr_numeric(event_indicator,'event_indicator',vector_only=TRUE);if(length(start)!=length(stop)||length(event)!=length(stop)||any(start<0)||any(stop<=start)||any(!event %in% c(0,1))).cr_error('INVALID_RISK_INTERVAL','Require 0 <= entry < exit and binary event');list(start=start,stop=stop,event=event)}
.sv_matrix_list<-function(x)lapply(seq_len(nrow(x)),function(i)as.list(unname(x[i,])))
.sv_matrix<-function(x){if(is.matrix(x))return(x);do.call(rbind,lapply(x,unlist,use.names=FALSE))}
estimate_survival_curve<-function(entry_time,exit_time,event_indicator,weight_policy,weights=NULL,confidence_level=.95,target,training,model_id,model_version,context=NULL){
 t<-.sv_times(entry_time,exit_time,event_indicator);w<-if(is.null(weights))rep(1,length(t$stop)) else .cr_numeric(weights,'weights',vector_only=TRUE)
 if(weight_policy!='frequency'||length(w)!=length(t$stop)||any(w<0)||any(w!=floor(w))||!is.finite(sum(w))||sum(w)<=0||sum(w)>=2^53).cr_error('INVALID_WEIGHTS','Nonnegative integer frequency weights with positive total required')
 c<-.sv_scalar(confidence_level,'confidence_level',0,1);if(c %in% c(0,1)).cr_error('INVALID_INPUT','Interior confidence required')
 times<-sort(unique(t$stop[w>0]));surv<-1;green<-0;curve<-list();z<-stats::qnorm((1+c)/2)
 for(time in times){risk<-sum(w[t$start<time&t$stop>=time]);d<-sum(w[t$stop==time&t$event==1]);censored<-sum(w[t$stop==time&t$event==0]);if(risk<=0).cr_error('EMPTY_RISK_SET','Exit has no active risk set')
 if(d==risk){surv<-0;lower<-upper<-0}else{surv<-surv*(1-d/risk);green<-green+d/(risk*(risk-d));if(surv %in% c(0,1))lower<-upper<-surv else{se<-sqrt(green)/abs(log(surv));eta<-log(-log(surv));lower<-exp(-exp(min(eta+z*se,709)));upper<-exp(-exp(eta-z*se))}}
 curve[[length(curve)+1L]]<-list(time=time,at_risk=risk,events=d,censored=censored,survival=surv,lower=lower,upper=upper,greenwood_sum=green)}
 gaps<-list();right<-NULL;active<-which(w>0);active<-active[order(t$start[active],t$stop[active])];for(i in active){if(!is.null(right)&&t$start[i]>right)gaps[[length(gaps)+1L]]<-list(start=right,stop=t$start[i]);right<-if(is.null(right))t$stop[i] else max(right,t$stop[i])}
 params<-list(kind='kaplan_meier',risk_support_gaps=gaps,curve=curve,support_end=max(t$stop[w>0]),support_start=min(t$start[w>0]),entry_time=as.list(t$start),exit_time=as.list(t$stop),frequency_weights=as.list(w));diag<-list(risk_interval='(entry,exit]',confidence_level=c,confidence_method='greenwood_log_log',weight_policy=weight_policy,independence_assumption='independent_subjects_noninformative_censoring_and_truncation',no_events=!any(t$event[w>0]==1),boundary_intervals='asymptotic_degenerate_not_exact_small_sample_bounds')
 .cr_fit_result(.sv_model('estimate_survival_curve',character(),params,target,training,model_id,model_version,diag),'survival.estimate_survival_curve',diag,context)
}
estimate_multistate_transitions<-function(event_history,states,allowed_transitions,initial_state,target,training,model_id,model_version,context=NULL){
 rows<-.sv_rows(event_history);states<-.sv_strings(states,'states');if(!initial_state %in% states).cr_error('INVALID_STATE','Unknown initial state')
 if(!is.list(allowed_transitions)||any(vapply(allowed_transitions,function(e){e<-unlist(e);length(e)!=2||any(!e %in% states)||e[1]==e[2]},logical(1)))).cr_error('INVALID_GRAPH','Directed non-self pairs required')
 graph<-lapply(allowed_transitions,function(e)as.list(unlist(e,use.names=FALSE)));keys<-vapply(graph,.cr_hash,'');if(anyDuplicated(keys)).cr_error('INVALID_GRAPH','Duplicate graph edge');data<-list();entities<-list()
 for(r in rows){entity<-r$entity_id;origin<-r$from_state;destination<-r$to_state;start<-.sv_scalar(r$start,'start',0);stop<-.sv_scalar(r$stop,'stop',0)
 if(!is.character(entity)||length(entity)!=1||is.na(entity)||!nzchar(entity)||stop<=start||is.null(origin)||!origin %in% states||(!is.null(destination)&&!destination %in% states)).cr_error('INVALID_RISK_INTERVAL','Named entity/state and positive interval required')
 if(!is.null(destination)&&destination!=origin&&!.cr_hash(list(origin,destination)) %in% keys).cr_error('FORBIDDEN_TRANSITION','Transition absent from graph')
 row<-list(entity_id=entity,start=start,stop=stop,from_state=origin,to_state=destination);data[[length(data)+1L]]<-row;entities[[entity]]<-c(entities[[entity]],list(row))}
 for(history in entities){history<-history[order(vapply(history,`[[`,0,'start'))];if(length(history)>1)for(i in 2:length(history)){previous<-history[[i-1]];current<-history[[i]];expected<-if(is.null(previous$to_state))previous$from_state else previous$to_state;if(current$start!=previous$stop||current$from_state!=expected).cr_error('INVALID_HISTORY','Intervals must be contiguous and state-consistent')}}
 transitions<-Filter(function(r)!is.null(r$to_state)&&r$to_state!=r$from_state,data);times<-sort(unique(vapply(transitions,`[[`,0,'stop')));increments<-risks<-products<-counts<-list();P<-diag(length(states))
 for(time in times){risk<-vapply(states,function(s)sum(vapply(data,function(r)r$from_state==s&&r$start<time&&time<=r$stop,logical(1))),0);count<-matrix(0,length(states),length(states));for(r in transitions)if(r$stop==time){i<-match(r$from_state,states);j<-match(r$to_state,states);count[i,j]<-count[i,j]+1}
 if(any((risk==0)&rowSums(count)>0)||any(rowSums(count)>risk)).cr_error('EMPTY_RISK_SET','Events inconsistent with risk sets')
 A<-matrix(0,length(states),length(states));for(i in seq_along(states))if(risk[i]>0)A[i,]<-count[i,]/risk[i];diag(A)<- -rowSums(A);P<-P%*%(diag(length(states))+A);increments[[length(increments)+1L]]<-.sv_matrix_list(A);risks[[length(risks)+1L]]<-as.list(unname(risk));counts[[length(counts)+1L]]<-.sv_matrix_list(count);products[[length(products)+1L]]<-.sv_matrix_list(P)}
 if(length(graph))graph<-graph[order(vapply(graph,function(e)e[[1]],''),vapply(graph,function(e)e[[2]],''))]
 params<-list(kind='aalen_johansen',states=as.list(states),allowed_transitions=graph,initial_state=initial_state,event_times=as.list(times),hazard_increment_matrices=increments,risk_sets=risks,transition_counts=counts,transition_matrices=products,state_occupancy=lapply(products,function(v)v[[match(initial_state,states)]]),support_start=min(vapply(data,`[[`,0,'start')),support_end=max(vapply(data,`[[`,0,'stop')),risk_intervals=data)
 diagnostic<-list(estimator='Aalen-Johansen',risk_interval='(start,stop]',entity_count=length(entities),interval_count=length(data),transition_interpretation='time_inhomogeneous_Markov_given_state',unobserved_risk_rows='identity_increment_with_unidentified_transition_intensity',first_default='separate_absorbing_first_hit_projection_not_current_state_occupancy',independence_assumption='independent_entities_noninformative_censoring_and_truncation')
 .cr_fit_result(.sv_model('estimate_multistate_transitions',character(),params,target,training,model_id,model_version,diagnostic),'survival.estimate_multistate_transitions',diagnostic,context)
}
.sv_panel<-function(panel,X,feature_order,strata=NULL){
 rows<-.sv_rows(panel);features<-.sv_strings(feature_order,'feature_order',TRUE);x<-.cr_numeric(X,'X',allow_empty=TRUE);if(!is.matrix(x)||nrow(x)!=length(rows)||ncol(x)!=length(features)).cr_error('FEATURE_MISMATCH','Aligned panel matrix required')
 t<-.sv_times(vapply(rows,function(r).sv_scalar(r$start,'start'),0),vapply(rows,function(r).sv_scalar(r$stop,'stop'),0),vapply(rows,function(r).sv_scalar(r$event,'event'),0));groups<-if(is.null(strata))rep('all',length(rows)) else unlist(strata,use.names=FALSE)
 if(length(groups)!=length(rows)||!is.character(groups)||anyNA(groups)||any(!nzchar(groups))).cr_error('INVALID_STRATA','One stratum per row required');ids<-character(length(rows));histories<-list()
 for(i in seq_along(rows)){r<-rows[[i]];id<-r$entity_id;if(!is.character(id)||length(id)!=1L||is.na(id)||!nzchar(id)).cr_error('INVALID_ENTITY','Named entity required');if(length(features)&&.sv_scalar(r$covariate_time,'covariate_time')>t$start[i]).cr_error('LOOKAHEAD','Covariates must be available by interval start');ids[i]<-id;histories[[id]]<-c(histories[[id]],i)}
 for(h in histories){h<-h[order(t$start[h])];if(length(h)>1L)for(j in 2:length(h)){a<-h[j-1];b<-h[j];if(t$event[a]==1||t$start[b]!=t$stop[a]).cr_error('INVALID_HISTORY','Intervals must be contiguous and terminate at event')}}
 c(list(rows=rows,x=x,features=features,ids=ids,groups=groups),t)
}
.sv_cox_stats<-function(start,stop,event,x,strata,beta,ties,weights=NULL){
 w<-if(is.null(weights))rep(1,length(start)) else weights;rr0<-exp(as.vector(x%*%beta));if(any(!is.finite(rr0))).cr_error('NUMERICAL_RANGE','Cox risk score overflow');baseline<-list();p<-ncol(x);score<-numeric(2*p);information<-matrix(0,2*p,2*p);center<-if(any(event==1))mean(stop[event==1]) else 0;residuals<-list()
 for(s in sort(unique(strata)))for(time in sort(unique(stop[event==1&strata==s]))){risk<-start<time&stop>=time&strata==s;deaths<-stop==time&event==1&strata==s;d<-sum(deaths);rr<-rr0[risk]*w[risk];dd<-rr0[deaths]*w[deaths];R<-sum(rr);D<-sum(dd);if(R<=0).cr_error('EMPTY_RISK_SET','Event without risk support');baseline[[length(baseline)+1L]]<-list(stratum=s,time=time,increment=sum(w[deaths])/R,at_risk=sum(risk),events=d,weighted_risk=R)
 if(p&&is.null(weights)){z<-cbind(x,x*(time-center));zr<-z[risk,,drop=FALSE];zd<-z[deaths,,drop=FALSE];R1<-as.vector(crossprod(rr,zr));R2<-crossprod(zr,rr*zr);D1<-as.vector(crossprod(dd,zd));D2<-crossprod(zd,dd*zd);score<-score+colSums(zd);expected<-numeric(p)
 for(j in 0:(d-1)){fraction<-if(ties=='efron')j/d else 0;den<-R-fraction*D;mu<-(R1-fraction*D1)/den;score<-score-mu;information<-information+(R2-fraction*D2)/den-tcrossprod(mu);expected<-expected+mu[seq_len(p)]}
 residuals[[length(residuals)+1L]]<-list(stratum=s,time=time,events=d,summed_schoenfeld=as.list(unname(colSums(x[deaths,,drop=FALSE])-expected)))}}
 ph<-list(method='efficient_score_for_identity_time_interactions',time_center=center,applicability='NOT_APPLICABLE',reason='NO_COVARIATES_OR_WEIGHTED_IPCW',global_statistic=NULL,global_p_value=NULL,per_feature=list(),schoenfeld_event_sums=residuals)
 if(p&&is.null(weights)){first<-seq_len(p);second<-p+first;answer<-tryCatch({eff<-information[second,second,drop=FALSE]-information[second,first,drop=FALSE]%*%solve(information[first,first,drop=FALSE],information[first,second,drop=FALSE]);u<-score[second]-information[second,first,drop=FALSE]%*%solve(information[first,first,drop=FALSE],score[first]);e<-eigen(eff,symmetric=TRUE,only.values=TRUE)$values;if(min(e)<=max(e)*1e-10)NULL else list(eff=eff,u=as.vector(u))},error=function(e)NULL)
 if(is.null(answer))ph$reason<-'TIME_INTERACTION_NOT_IDENTIFIABLE' else{stat<-as.numeric(crossprod(answer$u,solve(answer$eff,answer$u)));ph$applicability<-'APPLICABLE';ph['reason']<-list(NULL);ph$global_statistic<-stat;ph$global_p_value<-stats::pchisq(stat,p,lower.tail=FALSE);ph$per_feature<-lapply(seq_len(p),function(j)list(score=answer$u[j],information=answer$eff[j,j],statistic=answer$u[j]^2/answer$eff[j,j],p_value=stats::pchisq(answer$u[j]^2/answer$eff[j,j],1,lower.tail=FALSE)))}}
 list(baseline=baseline,ph=ph)
}
.sv_cox_backend<-function(start,stop,event,x,groups,ids,ties,covariance,max_iter,tolerance,weights=NULL){
 .weight <- .id <- NULL # model.frame resolves these names in data=frame.
 p<-ncol(x);if(!p)return(list(beta=numeric(),cov=matrix(numeric(),0,0),ll=NULL,scaled=0,warnings=character()))
 if(qr(cbind(1,x),tol=1e-10)$rank!=p+1L).cr_error('NON_IDENTIFIABLE','Cox design has implicit intercept or collinearity')
 frame<-as.data.frame(x);names(frame)<-paste0('x',seq_len(p));frame$.start<-start;frame$.stop<-stop;frame$.event<-event;frame$.stratum<-groups;frame$.id<-ids;frame$.weight<-if(is.null(weights))rep(1,length(start)) else weights
 Surv<-survival::Surv;strata<-survival::strata;formula<-stats::as.formula(paste('Surv(.start,.stop,.event)~',paste(paste0('x',seq_len(p)),collapse='+'),'+strata(.stratum)'));warnings<-character()
 fit<-withCallingHandlers(tryCatch(survival::coxph(formula,data=frame,weights=.weight,cluster=.id,robust=covariance=='cluster_robust',ties=ties,control=survival::coxph.control(iter.max=max_iter,eps=tolerance,timefix=FALSE),x=TRUE,y=TRUE,model=TRUE),error=function(e).cr_error('NUMERICAL_FAILURE',conditionMessage(e))),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})
 beta<-as.numeric(stats::coef(fit));cov<-as.matrix(stats::vcov(fit));if(any(!is.finite(beta))||any(!is.finite(cov))||min(eigen(cov,symmetric=TRUE,only.values=TRUE)$values)<=0).cr_error('NON_IDENTIFIABLE','Finite identified Cox fit required')
 if(any(grepl('converg|infinite',warnings,ignore.case=TRUE))).cr_error('NON_CONVERGENCE','Cox convergence warning')
 list(beta=beta,cov=cov,ll=tail(fit$loglik,1),scaled=NULL,warnings=warnings)
}
fit_cox_ph<-function(start_stop_panel,X,feature_order,ties,strata=NULL,covariance='model_based',target,training,model_id,model_version,max_iter=200,tolerance=1e-9,context=NULL){
 a<-.sv_panel(start_stop_panel,X,feature_order,strata);if(!ties %in% c('efron','breslow')||!covariance %in% c('model_based','cluster_robust')).cr_error('INVALID_ESTIMATOR','Declare ties and covariance');if(!any(a$event==1)).cr_error('INSUFFICIENT_EVENTS','Cox requires events');tol<-.sv_scalar(tolerance,'tolerance',0,1);iterations<-.sv_scalar(max_iter,'max_iter',1);if(tol==0||iterations!=floor(iterations)).cr_error('INVALID_INPUT','Positive tolerance and integer max_iter required')
 fit<-.sv_cox_backend(a$start,a$stop,a$event,a$x,a$groups,a$ids,ties,covariance,iterations,tol);statistics<-.sv_cox_stats(a$start,a$stop,a$event,a$x,a$groups,fit$beta,ties)
 params<-list(kind='cox_ph',coefficients=as.list(fit$beta),covariance=.sv_matrix_list(fit$cov),ties=ties,baseline_method='breslow_uncentered',baseline=statistics$baseline,strata=as.list(sort(unique(a$groups))),support_start=min(a$start),support_end=max(a$stop),risk_intervals=lapply(seq_along(a$start),function(i)list(start=a$start[i],stop=a$stop[i],stratum=a$groups[i])))
 diag<-list(backend=if(length(a$features))'survival::coxph' else 'closed_form_risk_sets',log_partial_likelihood=fit$ll,scaled_score=fit$scaled,converged=TRUE,covariance_type=covariance,ph_diagnostic=statistics$ph,ph_assumption='independent_entities; pointwise score diagnostics are not proof of proportionality',warnings=as.list(fit$warnings),risk_interval='(start,stop]',baseline_prediction='exp(-Breslow_cumulative_hazard)')
 .cr_fit_result(.sv_model('fit_cox_ph',a$features,params,target,training,model_id,model_version,diag),'survival.fit_cox_ph',diag,context)
}
.sv_aft_ll<-function(time,event,x,beta,scale,distribution){z<-(log(time)-as.vector(cbind(1,x)%*%beta))/scale;if(distribution=='weibull'){logS<- -exp(z);logf<-z-exp(z)-log(time)-log(scale)}else if(distribution=='lognormal'){logS<-stats::pnorm(-z,log.p=TRUE);logf<-stats::dnorm(z,log=TRUE)-log(time)-log(scale)}else{logS<-stats::plogis(-z,log.p=TRUE);logf<-stats::dlogis(z,log=TRUE)-log(time)-log(scale)};ifelse(event==1,logf,logS)}
fit_aft_model<-function(durations,events,X,feature_order,distribution,target,training,model_id,model_version,max_iter=500,tolerance=1e-9,context=NULL){
 time<-.cr_numeric(durations,'durations',vector_only=TRUE);event<-.cr_numeric(events,'events',vector_only=TRUE);features<-.sv_strings(feature_order,'feature_order',TRUE);x<-.cr_numeric(X,'X',allow_empty=TRUE)
 if(!is.matrix(x)||nrow(x)!=length(time)||ncol(x)!=length(features)||length(event)!=length(time)||any(time<=0)||any(!event %in% c(0,1))).cr_error('INVALID_SURVIVAL_DATA','Positive durations, binary events and aligned X required')
 if(!distribution %in% c('weibull','lognormal','loglogistic')).cr_error('INVALID_DISTRIBUTION','Declare supported AFT distribution');if(!any(event==1)||qr(cbind(1,x))$rank!=ncol(x)+1L).cr_error('NON_IDENTIFIABLE','Events and full-rank AFT design required')
 iterations<-.sv_scalar(max_iter,'max_iter',1);tol<-.sv_scalar(tolerance,'tolerance',0,1);if(iterations!=floor(iterations)||tol==0).cr_error('INVALID_INPUT','Positive max_iter and tolerance required')
 frame<-as.data.frame(x);names(frame)<-if(ncol(x))paste0('x',seq_len(ncol(x))) else character();frame$.time<-time;frame$.event<-event;Surv<-survival::Surv;formula<-stats::as.formula(paste('Surv(.time,.event)~',if(ncol(x))paste(names(frame)[seq_len(ncol(x))],collapse='+') else '1'));warnings<-character()
 fit<-withCallingHandlers(tryCatch(survival::survreg(formula,data=frame,dist=distribution,control=survival::survreg.control(maxiter=iterations,rel.tolerance=tol)),error=function(e).cr_error('NUMERICAL_FAILURE',conditionMessage(e))),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')})
 beta<-as.numeric(stats::coef(fit));scale<-fit$scale;cov<-as.matrix(stats::vcov(fit));ll<-.sv_aft_ll(time,event,x,beta,scale,distribution)
 if(any(!is.finite(beta))||any(!is.finite(cov))||any(!is.finite(ll))||min(eigen(cov,symmetric=TRUE,only.values=TRUE)$values)<=0).cr_error('NON_IDENTIFIABLE','Finite positive-information AFT fit required')
 if(any(grepl('converg|infinite',warnings,ignore.case=TRUE))).cr_error('NON_CONVERGENCE','AFT convergence warning')
 if(abs(sum(ll)-tail(fit$loglik,1))>1e-7*(1+abs(sum(ll)))).cr_error('NUMERICAL_FAILURE','AFT parameter likelihood mismatch')
 params<-list(kind='aft',distribution=distribution,coefficients=as.list(beta),log_time_scale=scale,covariance_beta_log_scale=.sv_matrix_list(cov),support_start=0,support_end=max(time));diag<-list(backend='survival::survreg',parameterization='log(T)=intercept+X beta+scale*epsilon',log_likelihood=sum(ll),row_log_likelihood=as.list(ll),converged=TRUE,warnings=as.list(warnings),censoring='independent_right_censoring',extrapolation='parametric_tail_requires_explicit_prediction_policy')
 .cr_fit_result(.sv_model('fit_aft_model',features,params,target,training,model_id,model_version,diag),'survival.fit_aft_model',diag,context)
}
fit_discrete_hazard<-function(person_period_panel,X,feature_order,period_grid,link,partial_period_policy,target,training,model_id,model_version,max_iter=200,tolerance=1e-9,context=NULL){
 a<-.sv_panel(person_period_panel,X,feature_order);grid<-.cr_numeric(period_grid,'period_grid',vector_only=TRUE);if(length(grid)<2||grid[1]<0||any(diff(grid)<=0)||!link %in% c('logit','cloglog')||!partial_period_policy %in% c('exclude_censored','cloglog_exposure')).cr_error('INVALID_PERIOD_CONTRACT','Increasing grid and explicit link/partial-period policy required')
 if(partial_period_policy=='cloglog_exposure'&&link!='cloglog').cr_error('INVALID_PERIOD_CONTRACT','Exposure scaling requires cloglog');periods<-integer(length(a$rows));keep<-logical(length(a$rows));offset<-numeric(length(a$rows))
 for(i in seq_along(a$rows)){r<-a$rows[[i]];k<-.sv_scalar(r$period,'period',0,length(grid)-2);if(k!=floor(k)).cr_error('INVALID_PERIOD_CONTRACT','Zero-based integer period required');k<-k+1L;if(!(grid[k]<=a$start[i]&&a$start[i]<a$stop[i]&&a$stop[i]<=grid[k+1])).cr_error('INVALID_PERIOD_CONTRACT','Interval crosses period');if(is.null(r$interval_end_type)||!r$interval_end_type %in% c('scheduled','censor')||(a$event[i]==1&&r$interval_end_type!='scheduled')).cr_error('INVALID_PERIOD_CONTRACT','Binary interval outcomes require scheduled event windows')
 if(partial_period_policy=='exclude_censored'){if(a$start[i]!=grid[k]).cr_error('INVALID_PERIOD_CONTRACT','Grouped logit requires boundary entry');complete<-a$stop[i]==grid[k+1];if(!complete&&a$event[i]==1).cr_error('INVALID_PERIOD_CONTRACT','Partial event windows require cloglog exposure');keep[i]<-complete}else keep[i]<-TRUE
 periods[i]<-k;offset[i]<-if(partial_period_policy=='cloglog_exposure')log((a$stop[i]-a$start[i])/(grid[k+1]-grid[k])) else 0}
 dummies<-diag(length(grid)-1)[periods,,drop=FALSE];design<-cbind(dummies,a$x);names<-c(paste0('period_',0:(length(grid)-2)),a$features);if(anyDuplicated(names)).cr_error('FEATURE_MISMATCH','Internal period-name collision')
 fitted<-fit_binary_glm(design[keep,,drop=FALSE],a$event[keep],feature_order=names,link=link,fit_intercept=FALSE,target=target,training=training,model_id=model_id,model_version=model_version,offset=offset[keep],max_iter=max_iter,tolerance=tolerance);coef<-unlist(fitted$model$parameters$coefficients);K<-length(grid)-1L
