fit_cause_specific_hazards<-function(start_stop_panel,X,event_types,feature_order,causes,ties,strata=NULL,target,training,model_id,model_version,covariance='model_based',max_iter=200,tolerance=1e-9,context=NULL){
 rows<-.sv_rows(start_stop_panel);causes<-.sv_strings(causes,'causes');if(length(event_types)!=length(rows)||any(vapply(event_types,function(e)!is.null(e)&&!e %in% causes,logical(1)))).cr_error('INVALID_CAUSE','Null censoring or declared cause required')
 terminal<-Map(function(r,e){r$event<-as.numeric(!is.null(e));r},rows,event_types);.sv_panel(terminal,X,feature_order,strata);models<-list()
 for(cause in causes){specific<-Map(function(r,e){r$event<-as.numeric(!is.null(e)&&e==cause);r},rows,event_types);fit<-fit_cox_ph(specific,X,feature_order,ties,strata,covariance,target,training,paste0(model_id,':',cause),model_version,max_iter,tolerance);models[[length(models)+1L]]<-list(cause=cause,parameters=fit$model$parameters,diagnostics=fit$diagnostics)}
 params<-list(kind='cause_specific',causes=as.list(causes),cause_models=models,support_start=min(vapply(models,function(m)m$parameters$support_start,0)),support_end=min(vapply(models,function(m)m$parameters$support_end,0)),joint_integration='exponential_total_increment_with_proportional_cause_allocation');diag<-list(ties=ties,competing_event_fit_policy='censor_at_competing_terminal_event',prediction='all_cause_hazards_integrated_jointly; cause_CIF_is_not_1_minus_cause_specific_survival')
