}
.sv_fg_expand<-function(time,events,x,ids,cause,groups){
 target_times<-sort(unique(time[vapply(events,function(e)!is.null(e)&&e==cause,logical(1))]));curves<-list();rows<-list();xx<-list();weights<-numeric();censored<-vapply(events,is.null,logical(1))
 for(group in sort(unique(groups))){active<-groups==group;curve<-list();G<-1;for(t in sort(unique(time[active]))){censor<-active&time==t&censored;risk<-sum(active&time>t)+sum(censor);d<-sum(censor);if(d){G<-G*(1-d/risk);curve[[length(curve)+1L]]<-list(time=t,survival=G,risk=risk,censored=d)}};curves[[group]]<-curve}
 Gleft<-function(t,group){before<-Filter(function(r)r$time<t,curves[[group]]);if(length(before))tail(before,1)[[1]]$survival else 1};previous<-0
 for(t in target_times){for(i in seq_along(time)){T<-time[i];if(T>=t)w<-1 else if(!is.null(events[[i]])&&events[[i]]!=cause){den<-Gleft(T,groups[i]);if(den<=0).cr_error('INSUFFICIENT_CENSORING_SUPPORT','Positive censoring survival required');w<-Gleft(t,groups[i])/den}else next;if(w<=0)next
 rows[[length(rows)+1L]]<-list(entity_id=ids[i],start=previous,stop=t,event=as.numeric(T==t&&!is.null(events[[i]])&&events[[i]]==cause),covariate_time=0);xx[[length(xx)+1L]]<-x[i,,drop=FALSE];weights<-c(weights,w)};previous<-t}
 list(rows=rows,x=do.call(rbind,xx),weights=weights,curves=curves)
}
fit_fine_gray<-function(event_times,event_types,X,cause_of_interest,feature_order,censoring_spec,target,training,model_id,model_version,max_iter=200,tolerance=1e-9,context=NULL){
 time<-.cr_numeric(event_times,'event_times',vector_only=TRUE);features<-.sv_strings(feature_order,'feature_order',TRUE);x<-.cr_numeric(X,'X',allow_empty=TRUE)
 if(!is.matrix(x)||nrow(x)!=length(time)||ncol(x)!=length(features)||length(event_types)!=length(time)||any(time<=0)||any(vapply(event_types,function(e)!is.null(e)&&(!is.character(e)||length(e)!=1L||is.na(e)||!nzchar(e)),logical(1)))).cr_error('INVALID_SURVIVAL_DATA','Positive times and aligned baseline covariates required')
 if(!is.character(cause_of_interest)||length(cause_of_interest)!=1L||!cause_of_interest %in% unlist(event_types)).cr_error('INSUFFICIENT_EVENTS','Observed cause of interest required')
 if(!is.list(censoring_spec)||!identical(censoring_spec$estimator,'kaplan_meier')||!identical(censoring_spec$independence_assumption,'independent_within_censoring_group')).cr_error('INVALID_CENSORING_MODEL','Declare within-group independent reverse-KM censoring model')
 groups<-if(is.null(censoring_spec$groups))rep('all',length(time)) else unlist(censoring_spec$groups,use.names=FALSE);if(length(groups)!=length(time)||!is.character(groups)||anyNA(groups)||any(!nzchar(groups))).cr_error('INVALID_CENSORING_MODEL','One censoring group per subject required')
 iterations<-.sv_scalar(max_iter,'max_iter',1);tol<-.sv_scalar(tolerance,'tolerance',0,1);if(iterations!=floor(iterations)||tol==0).cr_error('INVALID_INPUT','Positive integer max_iter and tolerance required')
 ids<-paste0('subject_',seq_along(time)-1L);a<-.sv_fg_expand(time,event_types,x,ids,cause_of_interest,groups);start<-vapply(a$rows,`[[`,0,'start');stop<-vapply(a$rows,`[[`,0,'stop');event<-vapply(a$rows,`[[`,0,'event');id<-vapply(a$rows,`[[`,'','entity_id')
 fit<-.sv_cox_backend(start,stop,event,a$x,rep('all',length(start)),id,'efron','model_based',max_iter,tolerance,a$weights);baseline<-.sv_cox_stats(start,stop,event,a$x,rep('all',length(start)),fit$beta,'efron',a$weights)$baseline
 params<-list(kind='fine_gray',cause=cause_of_interest,coefficients=as.list(fit$beta),conditional_ipcw_covariance=.sv_matrix_list(fit$cov),ties='efron',baseline_method='breslow_uncentered',baseline=baseline,strata=list('all'),censoring_curves=a$curves,support_start=0,support_end=max(time),risk_intervals=list(list(start=0,stop=max(time),stratum='all')))
 diag<-list(backend=if(length(features))'survival::coxph_weighted_counting_process' else 'closed_form_IPCW_risk_sets',log_partial_likelihood=fit$ll,expanded_rows=length(a$rows),expanded_risk_rows=a$rows,expanded_weights=as.list(a$weights),censoring_spec=censoring_spec,censor_tie_order='terminal_events_before_censoring',weight_formula='G(t-)/G(T-) for retained competing failures, otherwise one while observed at risk',covariance_limitation='conditional_on_estimated_IPCW; not full sampling covariance, resample original subjects and refit censoring for inference',warnings=as.list(fit$warnings),prediction='selected-cause CIF, complement is not all-event survival',covariates='baseline fixed; delayed entry and future time-varying competing-subject covariates not inferred')
 .cr_fit_result(.sv_model('fit_fine_gray',features,params,target,training,model_id,model_version,diag),'survival.fit_fine_gray',diag,context)
}
.sv_paths<-function(paths,features,start,end){
 rows<-.sv_rows(paths);grouped<-list()
 for(r in rows){key<-r$path_id;a<-.sv_scalar(r$start,'path.start',0);b<-.sv_scalar(r$stop,'path.stop',0);raw_x<-unlist(r$covariates,use.names=FALSE);if(is.null(raw_x))raw_x<-numeric();x<-.cr_numeric(raw_x,'covariates',allow_empty=TRUE,vector_only=TRUE);s<-if(is.null(r$stratum))'all' else r$stratum
 if(!is.character(key)||length(key)!=1L||is.na(key)||!nzchar(key)||b<=a||length(x)!=length(features)||!is.character(s)||length(s)!=1L||is.na(s)||!nzchar(s)).cr_error('INVALID_COVARIATE_PATH','Named paths and aligned covariates required')
 if(.sv_scalar(r$covariate_time,'covariate_time')>a).cr_error('LOOKAHEAD','Prediction covariates must be known by interval start');grouped[[key]]<-c(grouped[[key]],list(list(start=a,stop=b,x=x,stratum=s)))}
 for(key in names(grouped)){part<-grouped[[key]];part<-part[order(vapply(part,`[[`,0,'start'))];if(part[[1]]$start>start||tail(part,1)[[1]]$stop<end||(length(part)>1&&any(vapply(seq.int(2,length(part)),function(i)part[[i-1]]$stop!=part[[i]]$start,logical(1))))).cr_error('INCOMPLETE_PATH','Paths must cover horizon contiguously');grouped[[key]]<-part};grouped
}
predict_event_curves<-function(fitted_model,covariate_paths,horizon_grid,feature_order,target,initial_state=NULL,event_states=NULL,start_time=0,extrapolation='error',quantile_levels=NULL,context=NULL){
 model<-.cr_model(fitted_model);features<-.sv_strings(feature_order,'feature_order',TRUE);grid<-.cr_numeric(horizon_grid,'horizon_grid',vector_only=TRUE);start<-.sv_scalar(start_time,'start_time',0);params<-model$parameters;kind<-params$kind
 if(!identical(features,.sv_strings(model$feature_order,'model.feature_order',TRUE))||.cr_hash(target)!=.cr_hash(model$target)).cr_error('MODEL_CONTRACT_MISMATCH','Feature order and full target must match artifact')
 if(!startsWith(model$method_id,'survival.')||is.null(kind)||!kind %in% c('kaplan_meier','aalen_johansen','cox_ph','aft','discrete_hazard','cause_specific','fine_gray')).cr_error('UNSUPPORTED_MODEL','Supported frozen survival artifact required')
 if(any(grid<0)||any(diff(grid)<=0)).cr_error('INVALID_HORIZON','Nonnegative increasing elapsed horizons required')
 if(!extrapolation %in% c('error','flat','parametric')||(extrapolation=='parametric'&&kind!='aft')).cr_error('INVALID_EXTRAPOLATION','Parametric tails require AFT')
 end<-start+tail(grid,1);outside<-end>params$support_end||start<params$support_start;if(outside&&extrapolation=='error').cr_error('OUTSIDE_SUPPORT','Landmark/horizon outside observed support');levels<-if(is.null(quantile_levels))NULL else .cr_numeric(quantile_levels,'quantile_levels',vector_only=TRUE);if(!is.null(levels)&&(kind!='aft'||extrapolation!='parametric'||any(levels<=0)||any(levels>=1)||any(diff(levels)<=0))).cr_error('INVALID_QUANTILES','Ordered interior AFT quantiles require parametric-tail policy');curves<-list();unsupported<-list();unsupported_times<-list()
 if(kind %in% c('kaplan_meier','aalen_johansen')){
 if(length(covariate_paths)).cr_error('UNSUPPORTED_COVARIATES','Nonparametric population artifact requires empty paths')
 if(kind=='kaplan_meier'){
 entry<-unlist(params$entry_time);exit<-unlist(params$exit_time);w<-unlist(params$frequency_weights);if(!any(entry<=start&exit>start&w>0)&&extrapolation=='error').cr_error('INSUFFICIENT_RISK_SUPPORT','No landmark risk support')
 unsupported_times<-Filter(function(g)max(start,g$start)<min(end,g$stop),params$risk_support_gaps);if(length(unsupported_times)&&extrapolation=='error').cr_error('INSUFFICIENT_RISK_SUPPORT','Prediction crosses empty observation risk interval')
 S<-function(t){v<-Filter(function(r)r$time<=t,params$curve);if(length(v))tail(v,1)[[1]]$survival else 1};base<-S(start);if(base<=0).cr_error('IMPOSSIBLE_CONDITIONING','Zero surviving mass at landmark');surv<-vapply(grid,function(h)S(start+h)/base,0);F<-1-surv;curves<-list(list(path_id='population',survival=as.list(surv),cumulative_incidence=setNames(list(as.list(F)),target$event),marginal_probabilities=setNames(list(as.list(diff(c(0,F)))),target$event)))
 }else{
 states<-unlist(params$states,use.names=FALSE);initial<-if(is.null(initial_state))params$initial_state else initial_state;marked<-.sv_strings(if(is.null(event_states))list(target$event) else event_states,'event_states');n<-length(states);if(!initial %in% states||any(!marked %in% states)).cr_error('INVALID_STATE','Initial and marked states must be known')
 origin<-match(initial,states);mark<-match(marked,states);outgoing<-vapply(params$allowed_transitions,function(e)e[[1]],'');P<-Q<-diag(n);products<-occupancy<-list();hit<-numeric();times<-unlist(params$event_times,use.names=FALSE);position<-1L
 while(position<=length(times)&&times[position]<=start)position<-position+1L
 if(!any(vapply(params$risk_intervals,function(r)r$from_state==initial&&r$start<=start&&start<r$stop,logical(1)))&&extrapolation=='error').cr_error('INSUFFICIENT_RISK_SUPPORT','Initial-state landmark risk support absent')
 for(h in grid){while(position<=length(times)&&times[position]<=start+h){A<-.sv_matrix(params$hazard_increment_matrices[[position]]);risk<-unlist(params$risk_sets[[position]]);missing<-states[P[origin,]>1e-12&risk==0&states %in% outgoing];if(length(missing)){unsupported[[length(unsupported)+1L]]<-list(time=times[position],states=as.list(missing));if(extrapolation=='error').cr_error('INSUFFICIENT_RISK_SUPPORT','Positive state mass has unobserved outgoing hazard')}
 M<-diag(n)+A;P<-P%*%M;Mhit<-M;Mhit[mark,]<-diag(n)[mark,,drop=FALSE];Q<-Q%*%Mhit;position<-position+1L};products[[length(products)+1L]]<-.sv_matrix_list(P);occupancy[[length(occupancy)+1L]]<-as.list(P[origin,]);hit<-c(hit,sum(Q[origin,mark]))}
 base<-if(initial %in% marked)1 else 0;curves<-list(list(path_id='population',states=as.list(states),state_occupancy=occupancy,transition_matrices=products,first_hit_probability=as.list(hit),survival=as.list(1-hit),cumulative_incidence=list(first_hit=as.list(hit)),marginal_probabilities=list(first_hit=as.list(diff(c(base,hit))))))
 }
 }else{
 paths<-.sv_paths(covariate_paths,features,start,end)
 for(key in sort(names(paths))){part<-paths[[key]];at<-function(t){candidates<-Filter(function(r)r$start<t&&t<=r$stop,part);if(!length(candidates)&&t==start)candidates<-Filter(function(r)r$start<=t&&t<r$stop,part);if(!length(candidates)).cr_error('INCOMPLETE_PATH','Covariate path lacks risk instant');tail(candidates,1)[[1]]}
 quantiles<-NULL
 if(kind=='aft'){
 if(any(vapply(part,function(r)!identical(r$x,part[[1]]$x),logical(1)))).cr_error('UNSUPPORTED_COVARIATES','AFT requires fixed profile');eta<-sum(c(1,part[[1]]$x)*unlist(params$coefficients));scale<-params$log_time_scale;distribution<-params$distribution
