 if(!is.null(levels)){logtail<-base+log1p(-levels);zq<-if(distribution=='weibull')log(-logtail) else if(distribution=='lognormal')stats::qnorm(logtail,lower.tail=FALSE,log.p=TRUE) else log(-expm1(logtail))-logtail;logq<-eta+scale*zq;if(any(logq>709)).cr_error('NUMERICAL_RANGE','AFT quantile exceeds finite range');quantiles<-exp(logq)-start}
 }else if(kind=='discrete_hazard'){
