 if(length(cuts)>1)for(j in 2:length(cuts)){a<-cuts[j-1];b<-cuts[j];k<-findInterval(a,boundaries);if(k<1||k>=length(boundaries)){if(extrapolation!='flat').cr_error('OUTSIDE_SUPPORT','Discrete period not fitted');next};r<-at(b);eta<-params$period_intercepts[[k]]+sum(r$x*beta);fraction<-(b-a)/(boundaries[k+1]-boundaries[k]);if(params$link=='logit'){if(a!=boundaries[k]||b!=boundaries[k+1]).cr_error('INVALID_PERIOD_CONTRACT','Logit needs full periods and boundary covariates');S<-S*stats::plogis(-eta)}else S<-S*exp(-exp(min(eta,709))*fraction)}
 surv<-c(surv,S);previous<-endpoint};cifs<-setNames(list(1-surv),target$event)
 }else{
 causes<-if(kind=='cause_specific')unlist(params$causes,use.names=FALSE) else if(kind=='fine_gray')params$cause else target$event;components<-if(kind=='cause_specific')lapply(params$cause_models,`[[`,'parameters') else list(params)
 for(r in part)if(any(vapply(components,function(m)!r$stratum %in% unlist(m$strata),logical(1)))).cr_error('UNKNOWN_STRATUM','Prediction stratum not fitted')
 times<-sort(unique(unlist(lapply(components,function(m)vapply(Filter(function(b)b$time>start,m$baseline),`[[`,0,'time')))));position<-1L;S<-1;F<-numeric(length(causes));surv<-numeric();allF<-list()
 for(h in grid){while(position<=length(times)&&times[position]<=start+h){t<-times[position];r<-at(t);deltas<-vapply(components,function(m){base<-sum(vapply(Filter(function(b)b$stratum==r$stratum&&b$time==t,m$baseline),`[[`,0,'increment'));eta<-sum(r$x*unlist(m$coefficients));if(eta>709).cr_error('NUMERICAL_RANGE','Predicted hazard overflows');base*exp(eta)},0);total<-sum(deltas);if(total){F<-F+S*(-expm1(-total))*deltas/total;S<-S*exp(-total)};position<-position+1L};surv<-c(surv,S);allF[[length(allF)+1L]]<-F};Fmat<-do.call(rbind,allF);cifs<-setNames(lapply(seq_along(causes),function(i)Fmat[,i]),causes)
 }
 curves[[length(curves)+1L]]<-list(path_id=key,survival=as.list(surv),cumulative_incidence=lapply(cifs,as.list),marginal_probabilities=lapply(cifs,function(v)as.list(diff(c(0,v)))))
 if(!is.null(quantiles))curves[[length(curves)]]$conditional_event_quantiles<-as.list(quantiles)
 }
 }
 value<-list(horizon_grid=as.list(grid),start_time=start,curves=curves);if(!is.null(levels))value$quantile_levels<-as.list(levels);diag<-list(model_id=model$model_id,model_version=model$model_version,kind=kind,extrapolation=extrapolation,outside_observed_time_support=outside,unsupported_state_times=unsupported,unsupported_time_intervals=unsupported_times,survival_meaning=if(kind=='fine_gray')'complement_of_selected_cause_CIF_not_all_event_survival' else if(kind=='aalen_johansen')'no_first_hit_in_marked_states' else 'event_free_conditional_on_landmark',curve_integration=if(kind %in% c('cox_ph','cause_specific','fine_gray'))'joint_exponential_hazard_increments' else 'frozen_model',state_transition_assumption=if(kind=='aalen_johansen')'time_inhomogeneous_Markov_given_landmark_state' else NULL)
 .cr_result(value,'survival.predict_event_curves','probability',context,diagnostics=diag,limitations='Frozen forecasts preserve target and observation clock. Flat continuation is explicit extrapolation. First-hit incidence differs from reversible-state occupancy.',provenance=model$provenance)
}
